"""Small deterministic ragged-choice MLP; no game-policy or engine imports."""
import os
for _name in ['OPENBLAS_NUM_THREADS','OMP_NUM_THREADS','MKL_NUM_THREADS','VECLIB_MAXIMUM_THREADS']:os.environ[_name]='2'
import numpy as np

PARAMETERS=['w1','b1','w2']
def packed(rows):
 lengths=np.array([len(r['features'])for r in rows],dtype=np.int64);starts=np.r_[0,np.cumsum(lengths)[:-1]]
 return{'x':np.concatenate([np.array(r['features'],dtype=np.float64)for r in rows]),'valid':np.concatenate([np.array(r['valid'],dtype=bool)for r in rows]),
 'lengths':lengths,'starts':starts,'groups':np.repeat(np.arange(len(rows)),lengths),'targets':starts+np.array([r['targetIndex']for r in rows]),'rows':rows}
def scaler(data):
 mean=data['x'].mean(axis=0);std=data['x'].std(axis=0);constant=std<1e-12
 return{'mean':mean,'scale':np.where(constant,1.,std),'constant':constant}
def transformed(data,scale):
 raw=(data['x']-scale['mean'])/scale['scale'];outside=(np.abs(raw)>8).any(axis=1)|((np.abs(data['x']-scale['mean'])>1e-8)&scale['constant']).any(axis=1)
 result={**data,'x':np.clip(raw,-8,8),'ood':np.maximum.reduceat(outside,data['starts'])};return result
def initial(width,hidden,seed):
 rng=np.random.default_rng(seed)
 return{'w1':rng.normal(0,1/np.sqrt(width),(width,hidden)),'b1':np.zeros(hidden),'w2':rng.normal(0,1/np.sqrt(hidden),hidden)}
def logits(model,x):return np.tanh(x@model['w1']+model['b1'])@model['w2']
def probabilities(values,data,temperature=1):
 z=np.where(data['valid'],values/temperature,-1e100);maxima=np.maximum.reduceat(z,data['starts']);e=np.exp(z-maxima[data['groups']]);e[~data['valid']]=0
 totals=np.add.reduceat(e,data['starts']);assert np.all(totals>0)
 return e/totals[data['groups']]
def objective_gradient(model,data,l2):
 x=data['x'];hidden=np.tanh(x@model['w1']+model['b1']);p=probabilities(hidden@model['w2'],data)
 count=len(data['starts']);loss=float(-np.log(np.maximum(p[data['targets']],1e-300)).mean()+.5*l2*(np.square(model['w1']).sum()+np.square(model['w2']).sum()))
 derivative=p.copy();derivative[data['targets']]-=1;derivative/=count
 dh=derivative[:,None]*model['w2'][None,:]*(1-np.square(hidden))
 return loss,{'w1':x.T@dh+l2*model['w1'],'b1':dh.sum(axis=0),'w2':hidden.T@derivative+l2*model['w2']}
def subset(data,indices):
 sizes=data['lengths'][indices];starts=np.r_[0,np.cumsum(sizes)[:-1]]
 selected=np.concatenate([np.arange(data['starts'][i],data['starts'][i]+data['lengths'][i])for i in indices])
 return{'x':data['x'][selected],'valid':data['valid'][selected],'lengths':sizes,'starts':starts,'groups':np.repeat(np.arange(len(indices)),sizes),
 'targets':starts+(data['targets'][indices]-data['starts'][indices])}
def train(data,hidden,l2,seed,steps=400,batch=512,rate=.003,progress=None):
 model=initial(data['x'].shape[1],hidden,seed);first={k:np.zeros_like(v)for k,v in model.items()};second={k:np.zeros_like(v)for k,v in model.items()};rng=np.random.default_rng(seed^0x36b92871)
 for step in range(1,steps+1):
  indices=rng.integers(0,len(data['starts']),size=min(batch,len(data['starts'])));loss,grad=objective_gradient(model,subset(data,indices),l2)
  assert np.isfinite(loss)and all(np.isfinite(v).all()for v in grad.values())
  for k in PARAMETERS:
   first[k]=.9*first[k]+.1*grad[k];second[k]=.999*second[k]+.001*np.square(grad[k]);model[k]-=rate*(first[k]/(1-.9**step))/(np.sqrt(second[k]/(1-.999**step))+1e-8)
  if progress and step%100==0:progress(step,loss)
 return model
def class_prior(rows):
 counts=np.ones(3,dtype=np.float64)
 for r in rows:counts[0 if r['targetIndex']==r['cleanupIndex']else 1 if r['targetIndex']==r['beforeIndex']else 2]+=1
 return counts/counts.sum()
def prior_probabilities(data,prior):
 values=[]
 for r in data['rows']:
  kinds=np.full(len(r['valid']),2,dtype=int);kinds[r['cleanupIndex']]=0;kinds[r['beforeIndex']]=1;valid=np.array(r['valid']);counts=np.bincount(kinds[valid],minlength=3)
  mass=np.where(counts>0,prior,0);mass/=mass.sum();values.extend(np.where(valid,mass[kinds]/np.maximum(counts[kinds],1),0))
 return np.array(values)
def evaluation(data,model,temperature,prior,threshold=.85001):
 p=probabilities(logits(model,data['x']),data,temperature);base=prior_probabilities(data,prior);pred=[];confidence=[];proposal=[];correct=[]
 for i,r in enumerate(data['rows']):
  start=data['starts'][i];q=p[start:start+data['lengths'][i]];which=int(np.flatnonzero(q>=q.max()-1e-10)[0]);pred.append(which);confidence.append(float(q[which]));correct.append(which==r['targetIndex'])
  proposal.append(r['allowInference']and not bool(data['ood'][i])and which not in[r['cleanupIndex'],r['outsideIndex']]and float(q[which])>=threshold)
 loss=-np.log(np.maximum(p[data['targets']],1e-300));prior_loss=-np.log(np.maximum(base[data['targets']],1e-300))
 return{'probabilities':p,'losses':loss,'priorLosses':prior_loss,'predicted':np.array(pred),'confidence':np.array(confidence),'proposal':np.array(proposal,dtype=bool),'correct':np.array(correct,dtype=bool)}
def family_statistics(rows,evaluation,families):
 index={f:i for i,f in enumerate(families)};stats=np.zeros((len(families),5),dtype=np.float64)
 for i,r in enumerate(rows):
  j=index[r['familyId']];stats[j]+=[1,evaluation['priorLosses'][i]-evaluation['losses'][i],evaluation['proposal'][i],evaluation['proposal'][i]and evaluation['correct'][i],evaluation['correct'][i]]
 return stats
def bootstrap(stats,seed,repetitions=20000):
 rng=np.random.default_rng(seed);loss=[];precision=[];empty=0
 for start in range(0,repetitions,500):
  indices=rng.integers(0,len(stats),size=(min(500,repetitions-start),len(stats)));s=stats[indices].sum(axis=1);empty+=int((s[:,0]==0).sum())
  loss.extend(np.divide(s[:,1],s[:,0],out=np.zeros(len(s)),where=s[:,0]>0));precision.extend(np.divide(s[:,3],s[:,2],out=np.zeros(len(s)),where=s[:,2]>0))
 return{'loglossImprovement95':np.quantile(loss,[.025,.975],method='linear').tolist(),'proposalPrecision95':np.quantile(precision,[.025,.975],method='linear').tolist(),
 'emptyObservationResamples':empty,'repetitions':repetitions,'seed':seed,'rng':'NumPy PCG64 default_rng; whole original families; linear quantiles; zero-proposal resamples precision0'}
def summary(rows,e,all_families,seed):
 stats=family_statistics(rows,e,all_families);n=int(e['proposal'].sum());correct=int((e['proposal']&e['correct']).sum());families=int((stats[:,2]>0).sum());ci=bootstrap(stats,seed)
 result={'observations':len(rows),'wholeFamilies':len(all_families),'logloss':float(e['losses'].mean()),'priorLogloss':float(e['priorLosses'].mean()),
 'loglossImprovement':float((e['priorLosses']-e['losses']).mean()),'accuracy':float(e['correct'].mean()),'proposals':n,'proposalFamilies':families,'proposalCorrect':correct,
 'proposalPrecision':correct/n if n else None,'bootstrap':ci,'familyStatistics':[{'familyId':f,'observations':int(s[0]),'lossImprovementSum':float(s[1]),'proposals':int(s[2]),'proposalCorrect':int(s[3]),'correct':int(s[4])}for f,s in zip(all_families,stats)]}
 result['gates']={'atLeast100Proposals':n>=100,'atLeast60ProposalFamilies':families>=60,'precisionAtLeast90Percent':n>0 and correct/n>=.9,
 'familyPrecisionLowerAtLeast85Percent':ci['proposalPrecision95'][0]>=.85,'loglossImprovementAtLeast003':result['loglossImprovement']>=.03,
 'positiveFamilyLoglossLower':ci['loglossImprovement95'][0]>0,'noEmptyObservationBootstrapResamples':ci['emptyObservationResamples']==0};result['passed']=all(result['gates'].values());return result

import unittest
import numpy as np
from ranker import packed,initial,objective_gradient,train,logits,probabilities,class_prior,prior_probabilities,family_statistics,bootstrap
class RankerTests(unittest.TestCase):
 def test_gradient_matches_finite_differences_for_ragged_masked_choices(self):
  rng=np.random.default_rng(17);rows=[{'features':rng.normal(size=(n,5)).tolist(),'valid':[True]*(n-1)+[True],'targetIndex':n-1}for n in[2,4,3]];rows[1]['valid'][1]=False
  data=packed(rows);model=initial(5,4,31);loss,gradient=objective_gradient(model,data,.003)
  for k in model:
   for flat in range(min(7,model[k].size)):
    index=np.unravel_index(flat,model[k].shape);original=model[k][index];epsilon=1e-5;model[k][index]=original+epsilon;plus=objective_gradient(model,data,.003)[0];model[k][index]=original-epsilon;minus=objective_gradient(model,data,.003)[0];model[k][index]=original
    self.assertAlmostEqual((plus-minus)/(2*epsilon),gradient[k][index],places=6)
  self.assertTrue(np.isfinite(loss));p=probabilities(logits(model,data['x']),data);self.assertEqual(p[data['starts'][1]+1],0)
  for start,n in zip(data['starts'],data['lengths']):self.assertAlmostEqual(p[start:start+n].sum(),1)
 def test_optimizer_learns_a_known_candidate_signal_without_using_metadata(self):
  rows=[{'features':[[2,0],[-2,0],[0,1]],'valid':[True,True,True],'targetIndex':0}for _ in range(24)];data=packed(rows);model=train(data,8,1e-4,41,steps=400,batch=16)
  p=probabilities(logits(model,data['x']),data);self.assertGreater(float(p[0]),.9)
 def test_class_prior_renormalizes_only_available_groups(self):
  rows=[{'features':[[0],[0],[0]],'valid':[True,False,True],'targetIndex':0,'cleanupIndex':0,'beforeIndex':1}];prior=np.array([.3,.2,.5]);p=prior_probabilities(packed(rows),prior)
  np.testing.assert_allclose(p,[.375,0,.625]);np.testing.assert_allclose(class_prior(rows),[.5,.25,.25])
 def test_family_sums_and_zero_proposal_bootstrap_are_conservative(self):
  rows=[{'familyId':'a'},{'familyId':'a'},{'familyId':'b'}];e={'priorLosses':np.array([1,2,3]),'losses':np.array([.5,1,2]),'proposal':np.array([False,False,False]),'correct':np.array([True,False,True])}
  s=family_statistics(rows,e,['a','b','empty']);np.testing.assert_allclose(s,[[2,1.5,0,0,1],[1,1,0,0,1],[0,0,0,0,0]])
  ci=bootstrap(s,99,repetitions=200);self.assertEqual(ci['proposalPrecision95'],[0,0]);self.assertGreater(ci['emptyObservationResamples'],0)
if __name__=='__main__':unittest.main()

import assert from "node:assert/strict";
export interface Model{features:string[];mean:number[];scale:number[];constant:number[];temperature:number;confidenceThreshold:number;argmaxTieEpsilon:number;prior:number[];weights:{w1:number[][];b1:number[];w2:number[]};}
export interface ChoiceInput{features:number[][];valid:boolean[];cleanupIndex:number;outsideIndex:number;allowInference:boolean;beforeIndex:number;}
export function infer(model:Model,row:ChoiceInput){
 const d=model.mean.length,h=model.weights.w2.length;assert.equal(d,model.features.length);assert.equal(row.features.length,row.valid.length);assert(row.valid[row.outsideIndex]);
 let ood=false;const values=row.features.map(x=>{
  assert.equal(x.length,d);const normalized=x.map((v,i)=>{assert(Number.isFinite(v)&&model.scale[i]>0);const z=(v-model.mean[i])/model.scale[i];if(Math.abs(z)>8||model.constant[i]&&Math.abs(v-model.mean[i])>1e-8)ood=true;return Math.max(-8,Math.min(8,z));});
  let value=0;for(let j=0;j<h;j++){let activation=model.weights.b1[j];for(let i=0;i<d;i++)activation+=normalized[i]*model.weights.w1[i][j];value+=Math.tanh(activation)*model.weights.w2[j];}return value/model.temperature;
 });
 const maximum=Math.max(...values.filter((_,i)=>row.valid[i])),exps=values.map((v,i)=>row.valid[i]?Math.exp(v-maximum):0),total=exps.reduce((a,b)=>a+b,0),probabilities=exps.map(v=>v/total);
 const maxp=Math.max(...probabilities);const predictedIndex=probabilities.findIndex((p,i)=>row.valid[i]&&p>=maxp-model.argmaxTieEpsilon),confidence=probabilities[predictedIndex];
 const proposal=row.allowInference&&!ood&&predictedIndex!==row.cleanupIndex&&predictedIndex!==row.outsideIndex&&confidence>=model.confidenceThreshold;
 return{probabilities,predictedIndex,confidence,proposal,ood};
}
export function priorProbabilities(model:Model,row:ChoiceInput){
 const kind=row.valid.map((_,i)=>i===row.cleanupIndex?0:i===row.beforeIndex?1:2),counts=[0,0,0];row.valid.forEach((v,i)=>{if(v)counts[kind[i]]++;});
 const mass=model.prior.map((p,i)=>counts[i]?p:0),total=mass.reduce((a,b)=>a+b,0);return kind.map((k,i)=>row.valid[i]?mass[k]/total/counts[k]:0);
}

import {test,expect} from "bun:test";
import {readFileSync} from "node:fs";
import {infer,priorProbabilities,type Model} from "./inference";
const model:Model={features:["signal"],mean:[0],scale:[1],constant:[0],temperature:1,confidenceThreshold:.85001,argmaxTieEpsilon:1e-10,prior:[.3,.2,.5],weights:{w1:[[1]],b1:[0],w2:[10]}};
const row={features:[[4],[-4],[0]],valid:[true,true,true],cleanupIndex:1,beforeIndex:0,outsideIndex:2,allowInference:true};
test("stable masked choice posterior and high-confidence policy predicate",()=>{
 const p=infer(model,row);expect(p.proposal).toBe(true);expect(p.predictedIndex).toBe(0);expect(p.probabilities[0]).toBeCloseTo(Math.exp(10*Math.tanh(4))/(Math.exp(10*Math.tanh(4))+Math.exp(-10*Math.tanh(4))+1),12);
 const masked=infer(model,{...row,valid:[false,true,true]});expect(masked.probabilities[0]).toBe(0);expect(masked.predictedIndex).toBe(2);expect(masked.proposal).toBe(false);
});
test("incomplete public information and unsupported inputs cause abstention",()=>{
 expect(infer(model,{...row,allowInference:false}).proposal).toBe(false);expect(infer(model,{...row,features:[[9],[-4],[0]]}).ood).toBe(true);expect(infer(model,{...row,features:[[9],[-4],[0]]}).proposal).toBe(false);
 expect(infer({...model,constant:[1]},row).proposal).toBe(false);
});
test("predictor does not inspect labels, case identifiers or outcomes",()=>{
 const guarded=new Proxy(row,{get(target,key){if(!["features","valid","cleanupIndex","beforeIndex","outsideIndex","allowInference"].includes(String(key)))throw new Error("Forbidden data field");return Reflect.get(target,key);}});expect(infer(model,guarded)).toEqual(infer(model,row));
});
test("baseline redistributes unavailable category mass without touching labels",()=>{
 const p=priorProbabilities(model,{...row,valid:[false,true,true]});p.forEach((v,i)=>expect(v).toBeCloseTo([0,.375,.625][i],12));
});
test("independent NumPy synthetic posteriors agree including ragged masks and clipping",()=>{
 const fixture=JSON.parse(readFileSync(import.meta.dir+"/synthetic-inference.json","utf8"));for(const c of fixture.cases){const p=infer(fixture.model,c.row);p.probabilities.forEach((v,i)=>expect(Math.abs(v-c.probabilities[i])).toBeLessThan(1e-9));expect(p.ood).toBe(c.ood);}
});

/** Independent posterior, abstention, baseline, decision and family-sufficient-statistic verification. */
import assert from "node:assert/strict";
import {createHash} from "node:crypto";
import {readFileSync,writeFileSync,createReadStream,existsSync} from "node:fs";
import {createInterface} from "node:readline";
import {createGunzip,gunzipSync} from "node:zlib";
import {infer,priorProbabilities,type Model} from "./inference";
const p=import.meta.dir,read=(f:string)=>JSON.parse(readFileSync(`${p}/${f}`,"utf8")),sha=(b:Buffer)=>createHash("sha256").update(b).digest("hex"),reg=read("registration.json"),seal=sha(readFileSync(`${p}/registration.json`)),result=read("fit-result.json");
assert.equal(result.registrationSha256,seal);for(const f of reg.files)assert.equal(sha(readFileSync(`${p}/${f.path}`)),f.sha256);for(const f of reg.dataFiles)assert.equal(sha(readFileSync(`${p}/${f.path}`)),f.sha256);
const events=read("data-access-events.json");assert.deepEqual(events.map((e:any)=>e.fold),result.testOpened?["train","validation","test"]:["train","validation"]);
assert.equal(result.testOpened,existsSync(`${p}/test-opened.json`));if(result.testOpened){assert(result.validationPassed);const opened=read("test-opened.json"),sealed=read("candidate-seal.json");assert.equal(sha(readFileSync(`${p}/candidate-model.json`)),opened.candidateSha256);assert.equal(opened.candidateSha256,sealed.candidateSha256);assert(sealed.at<=opened.at&&!sealed.testReadBeforeSeal);}
const summaries:any[]=[];let total=0,maxError=0;
for(const fold of result.testOpened?["validation","test"]:["validation"]){
 const model=read(fold==="validation"?"validation-selected-model.json":"candidate-model.json")as Model,primary=read(`${fold}-result.json`);
 const predictions=new Map<string,any>();for(const line of gunzipSync(readFileSync(`${p}/${fold}-predictions.jsonl.gz`)).toString().trim().split("\n")){const r=JSON.parse(line);assert(!predictions.has(r.rowId));predictions.set(r.rowId,r);}
 const originalFamilies=[...new Set(read("data/case-ledger.json").filter((r:any)=>r.fold===fold).map((r:any)=>r.familyId))].sort();assert.deepEqual(primary.familyStatistics.map((r:any)=>r.familyId),originalFamilies);assert.equal(primary.bootstrap.repetitions,20000);assert.equal(primary.bootstrap.seed,fold==="validation"?reg.validationBootstrapSeed:reg.testBootstrapSeed);
 const fs=new Map<string,any>();for(const f of primary.familyStatistics)fs.set(f.familyId,{familyId:f.familyId,observations:0,lossImprovementSum:0,proposals:0,proposalCorrect:0,correct:0});
 let n=0,correct=0,proposals=0,proposalCorrect=0,lossSum=0,priorSum=0;
 for await(const line of createInterface({input:createReadStream(`${p}/data/${fold}.jsonl.gz`).pipe(createGunzip()),crlfDelay:Infinity})){
  const row=JSON.parse(line),expected=predictions.get(row.rowId);assert(expected);predictions.delete(row.rowId);const out=infer(model,row),prior=priorProbabilities(model,row),loss=-Math.log(Math.max(out.probabilities[row.targetIndex],1e-300)),priorLoss=-Math.log(Math.max(prior[row.targetIndex],1e-300));
  assert.equal(out.probabilities.length,expected.probabilities.length);out.probabilities.forEach((v,i)=>{const error=Math.abs(v-expected.probabilities[i]);maxError=Math.max(maxError,error);assert(error<=1e-9);});
  assert.equal(out.predictedIndex,expected.predictedIndex);assert.equal(out.proposal,expected.proposal);assert.equal(out.ood,expected.ood);assert.equal(row.targetIndex,expected.targetIndex);assert(Math.abs(loss-expected.loss)<1e-9&&Math.abs(priorLoss-expected.priorLoss)<1e-9);
  const c=out.predictedIndex===row.targetIndex,pc=out.proposal&&c;n++;correct+=+c;proposals+=+out.proposal;proposalCorrect+=+pc;lossSum+=loss;priorSum+=priorLoss;
  const f=fs.get(row.familyId);assert(f);f.observations++;f.lossImprovementSum+=priorLoss-loss;f.proposals+=+out.proposal;f.proposalCorrect+=+pc;f.correct+=+c;
 }
 assert.equal(predictions.size,0);assert.equal(n,primary.observations);assert.equal(correct/n,primary.accuracy);assert.equal(proposals,primary.proposals);assert.equal(proposalCorrect,primary.proposalCorrect);
 assert(Math.abs(lossSum/n-primary.logloss)<1e-9&&Math.abs(priorSum/n-primary.priorLogloss)<1e-9);for(const f of primary.familyStatistics){const observed=fs.get(f.familyId);for(const k of["observations","proposals","proposalCorrect","correct"])assert.equal(observed[k],f[k]);assert(Math.abs(observed.lossImprovementSum-f.lossImprovementSum)<1e-8);}
 const proposalFamilies=[...fs.values()].filter(f=>f.proposals>0).length;assert.equal(proposalFamilies,primary.proposalFamilies);
 const gates={atLeast100Proposals:proposals>=100,atLeast60ProposalFamilies:proposalFamilies>=60,precisionAtLeast90Percent:proposals>0&&proposalCorrect/proposals>=.9,familyPrecisionLowerAtLeast85Percent:primary.bootstrap.proposalPrecision95[0]>=.85,loglossImprovementAtLeast003:(priorSum-lossSum)/n>=.03,positiveFamilyLoglossLower:primary.bootstrap.loglossImprovement95[0]>0,noEmptyObservationBootstrapResamples:primary.bootstrap.emptyObservationResamples===0};assert.deepEqual(gates,primary.gates);assert.equal(Object.values(gates).every(Boolean),primary.passed);
 summaries.push({fold,observations:n,proposals,proposalFamilies,proposalCorrect,allGatesAgree:true});total+=n;
}
const verification={passed:true,registrationSha256:seal,observations:total,maxProbabilityError:maxError,allPolicyDecisionsMasksBaselinesAndFamilySufficientStatisticsExact:true,testOpened:result.testOpened,testOpeningFollowedValidationAndSealedArtifact:true,summaries,bootstrapRngIndependentlyReimplemented:false,modelActivated:false,newIndependentStrengthSamples:0};writeFileSync(`${p}/independent-verification.json`,JSON.stringify(verification,null,2)+"\n",{flag:"wx"});console.log(JSON.stringify(verification));
